import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import TvmSearchForm from './TvmSearchForm';
import TvmResult      from './TvmResult';

export default function TvmCalculator() {
  const navigate = useNavigate();
  const { state } = useLocation();
  const existingInternetPlan = state?.internetPlan;  
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [selectedStb,  setSelectedStb]  = useState('');

  const handlePlanSelect = plan => {
    setSelectedPlan(plan);
    setSelectedStb('');  // 셋톱박스 선택 초기화
  };

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h1 className="text-3xl font-bold mb-8 text-center">KT TV 계산기</h1>
      <p className="mt-2 text-base font-bold text-red-500">
        주의! 본 견적은 가견적이오니, 정확한 견적은 필히 추가로 확인하셔야 합니다.
      </p>

      {!selectedPlan ? (
        <TvmSearchForm onSelect={handlePlanSelect} />
      ) : (
        <>
          <TvmResult
            plan={selectedPlan}
            stbKey={selectedStb}
            onStbChange={setSelectedStb}
          />

          <div className="flex flex-col items-center space-y-4 mb-8">
            {/* ▶ 여기만 변경: InternetCalculator로 state 전달 */}
            <button
            type="button"
            onClick={() =>
              navigate('/internet', {
                state: {
                  internetPlan: existingInternetPlan,  // ← 기존 인터넷 플랜 유지
                  tvPlan: selectedPlan,
                  tvStb: selectedStb
                }
              })
            }
              className="w-48 bg-purple-600 text-white rounded py-2 hover:bg-purple-700 transition"
            >
              인터넷 결합 견적 보기
            </button>

            <button
              type="button"
              onClick={() => setSelectedPlan(null)}
              className="w-48 bg-blue-500 text-white rounded py-2 hover:bg-blue-600 transition"
            >
              다른 지니TV 검색하기
            </button>
          </div>
        </>
      )}

      <div className="mt-6 w-full text-center">
        <button
          onClick={() => navigate('/')}
          className="w-full px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 transition"
        >
          메인 메뉴로 돌아가기
        </button>
      </div>
    </div>
  );
}
